import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMap } from "react-leaflet";
import L from "leaflet";
import {
  Bike,
  CheckCircle2,
  Clock,
  MapPin,
  Navigation,
  Package,
  Radio
} from "lucide-react";
import markerIcon from "leaflet/dist/images/marker-icon.png";
import markerIcon2x from "leaflet/dist/images/marker-icon-2x.png";
import markerShadow from "leaflet/dist/images/marker-shadow.png";
import "leaflet/dist/leaflet.css";
import { apiFetch } from "./api";
import { openDeliverySocket } from "./deliverySocket";

const el = React.createElement;

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: markerIcon2x,
  iconUrl: markerIcon,
  shadowUrl: markerShadow
});

const RIDER_MARKER_ICON = L.divIcon({
  className: "campus-rider-marker",
  html:
    '<div class="campus-rider-marker-inner" style="width:16px;height:16px;border-radius:999px;background:linear-gradient(135deg,#0ea5e9,#2563eb);border:3px solid #fff;box-shadow:0 2px 10px rgba(0,0,0,.35);"></div>',
  iconSize: [20, 20],
  iconAnchor: [10, 10]
});

const DROPOFF_MARKER_ICON = L.divIcon({
  className: "campus-dropoff-marker",
  html:
    '<div style="width:20px;height:20px;border-radius:999px;background:linear-gradient(135deg,#7c3aed,#a78bfa);border:3px solid #fff;box-shadow:0 2px 10px rgba(0,0,0,.35);"></div>',
  iconSize: [22, 22],
  iconAnchor: [11, 11]
});

/** @typedef {"buyer" | "rider"} DeliveryLiveMode */
/** @typedef {"default" | "trackModal"} DeliveryLiveVariant */

const OSM_TILE = {
  url: "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
  attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
};

const STAGE_LABELS = {
  order_placed: "Order placed",
  confirmed: "Confirmed",
  preparing: "Preparing",
  ready_for_pickup: "Ready for pickup",
  picked_up: "Picked up",
  on_the_way: "On the way",
  delivered: "Delivered",
  cancelled: "Cancelled"
};

const STAGE_ORDER = [
  "order_placed",
  "confirmed",
  "preparing",
  "ready_for_pickup",
  "picked_up",
  "on_the_way",
  "delivered"
];

function timelineIcon(stage) {
  switch (stage) {
    case "delivered":
      return CheckCircle2;
    case "on_the_way":
      return Navigation;
    case "picked_up":
    case "ready_for_pickup":
      return Package;
    case "order_placed":
    case "confirmed":
    case "preparing":
      return Clock;
    default:
      return MapPin;
  }
}

/** @param {string|Date|undefined} at */
function formatFriendlyTime(at) {
  try {
    const d = new Date(at);
    if (!Number.isFinite(d.getTime())) return "";
    const diff = Date.now() - d.getTime();
    const sec = Math.floor(diff / 1000);
    let rel = "";
    if (sec < 45) rel = "Just now";
    else if (sec < 3600) rel = `${Math.floor(sec / 60)} min ago`;
    else if (sec < 86400) rel = `${Math.floor(sec / 3600)} hr ago`;
    else rel = `${Math.floor(sec / 86400)} d ago`;
    const clock = d.toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
    return `${rel} · ${clock}`;
  } catch {
    return "";
  }
}

function MapRecenter({ center, zoom }) {
  const map = useMap();
  useEffect(() => {
    map.setView(center, zoom, { animate: true });
  }, [center, zoom, map]);
  return null;
}

function FitDeliveryBounds({ points }) {
  const map = useMap();
  useEffect(() => {
    if (!points || points.length === 0) return;
    if (points.length === 1) {
      map.setView(points[0], 14, { animate: true });
      return;
    }
    try {
      const b = L.latLngBounds(points);
      map.fitBounds(b, { padding: [48, 48], maxZoom: 16, animate: true });
    } catch {
      /* ignore */
    }
  }, [points, map]);
  return null;
}

/**
 * @param {{ mode: DeliveryLiveMode; accessToken: string; orderId: string; className?: string; variant?: DeliveryLiveVariant }} props
 */
export function DeliveryLive({ mode, accessToken, orderId, className, variant = "default" }) {
  const [bundle, setBundle] = useState(null);
  const [loading, setLoading] = useState(true);
  const [fetchErr, setFetchErr] = useState("");
  const [busyStage, setBusyStage] = useState("");
  const [geoSharing, setGeoSharing] = useState(false);
  const [geoErr, setGeoErr] = useState("");
  /** @type {React.MutableRefObject<any>} */
  const watchRef = useRef(null);
  const lastSocketEmitRef = useRef(0);
  const socketRef = useRef(null);
  const [liveConnected, setLiveConnected] = useState(false);
  /** last rider location pushed over socket — for pulse feedback */
  const [lastLivePulse, setLastLivePulse] = useState(0);

  const loadBundle = useCallback(async () => {
    const d = await apiFetch(`/api/deliveries/order/${encodeURIComponent(orderId)}`, {
      headers: { Authorization: `Bearer ${accessToken}` }
    });
    setBundle(d);
    return d;
  }, [accessToken, orderId]);

  useEffect(() => {
    if (!accessToken || !orderId) return undefined;
    let cancelled = false;
    setFetchErr("");
    setLoading(true);
    loadBundle()
      .catch((ex) => {
        if (!cancelled) setFetchErr(ex?.message || "Could not load delivery");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [accessToken, orderId, loadBundle]);

  useEffect(() => {
    if (!accessToken || !orderId) return undefined;
    const s = openDeliverySocket(accessToken);
    socketRef.current = s;

    const subscribe = () => {
      s.emit("delivery:subscribe", { orderId }, () => {});
    };

    const onConn = () => {
      setLiveConnected(true);
      subscribe();
    };

    const onDisc = () => setLiveConnected(false);

    s.on("connect", onConn);
    s.on("disconnect", onDisc);
    if (s.connected) {
      setLiveConnected(true);
      subscribe();
    } else setLiveConnected(false);

    const onLoc = (p) => {
      if (!p || typeof p !== "object") return;
      setLastLivePulse(Date.now());
      setBundle((prev) => {
        if (!prev?.delivery) return prev;
        return {
          ...prev,
          delivery: {
            ...prev.delivery,
            riderLatitude: p.latitude,
            riderLongitude: p.longitude,
            riderLocationUpdatedAt: p.updatedAt || new Date().toISOString()
          }
        };
      });
    };

    const onUpdate = (p) => {
      if (!p || typeof p !== "object") return;
      setBundle((prev) => {
        if (!prev) return prev;
        const next = { ...prev };
        if (p.delivery) next.delivery = { ...prev.delivery, ...p.delivery };
        if (typeof p.orderStatus === "string" && prev.order && typeof prev.order === "object") {
          next.order = { ...prev.order, status: p.orderStatus };
        }
        return next;
      });
    };

    s.on("delivery:location", onLoc);
    s.on("delivery:update", onUpdate);

    return () => {
      s.off("connect", onConn);
      s.off("disconnect", onDisc);
      s.off("delivery:location", onLoc);
      s.off("delivery:update", onUpdate);
      try {
        s.close();
      } catch {
        /* ignore */
      }
      socketRef.current = null;
      setLiveConnected(false);
    };
  }, [accessToken, orderId]);

  const emitRiderCoords = useCallback(
    (lat, lng) => {
      const s = socketRef.current;
      if (!s?.connected || mode !== "rider") return;
      const now = Date.now();
      if (now - lastSocketEmitRef.current < 4000) return;
      lastSocketEmitRef.current = now;
      s.emit("delivery:rider-location", { orderId, latitude: lat, longitude: lng }, () => {});
    },
    [mode, orderId]
  );

  const postRiderCoords = useCallback(
    async (lat, lng) => {
      if (mode !== "rider") return;
      await apiFetch(`/api/deliveries/order/${encodeURIComponent(orderId)}/rider-location`, {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { latitude: lat, longitude: lng }
      });
    },
    [mode, orderId, accessToken]
  );

  useEffect(() => {
    if (!geoSharing || mode !== "rider") {
      if (watchRef.current != null && typeof navigator.geolocation?.clearWatch === "function") {
        navigator.geolocation.clearWatch(watchRef.current);
      }
      watchRef.current = null;
      return undefined;
    }
    if (!navigator.geolocation) {
      setGeoErr("Browser location is not available.");
      return undefined;
    }
    watchRef.current = navigator.geolocation.watchPosition(
      (pos) => {
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;
        emitRiderCoords(lat, lng);
        void postRiderCoords(lat, lng).catch(() => {});
      },
      () => setGeoErr("Location permission denied or unavailable."),
      { enableHighAccuracy: true, maximumAge: 15000, timeout: 20000 }
    );
    return () => {
      if (watchRef.current != null && typeof navigator.geolocation?.clearWatch === "function") {
        navigator.geolocation.clearWatch(watchRef.current);
      }
      watchRef.current = null;
    };
  }, [geoSharing, mode, emitRiderCoords, postRiderCoords]);

  const patchStage = async (stage) => {
    setBusyStage(stage);
    try {
      const { delivery } = await apiFetch(`/api/deliveries/order/${encodeURIComponent(orderId)}/stage`, {
        method: "PATCH",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { stage }
      });
      setBundle((prev) => (prev ? { ...prev, delivery } : prev));
    } catch (ex) {
      setGeoErr(typeof ex?.message === "string" ? ex.message : "Could not update stage");
    } finally {
      setBusyStage("");
    }
  };

  const delivery = bundle?.delivery;
  const rider = bundle?.rider;

  const rl = typeof delivery?.riderLatitude === "number" ? delivery.riderLatitude : null;
  const rln = typeof delivery?.riderLongitude === "number" ? delivery.riderLongitude : null;
  const dl = typeof delivery?.dropoffLatitude === "number" ? delivery.dropoffLatitude : null;
  const dln = typeof delivery?.dropoffLongitude === "number" ? delivery.dropoffLongitude : null;

  const { center, zoom, fitPoints } = useMemo(() => {
    let lat = 5.6037;
    let lng = -0.187;
    if (rl != null && rln != null) {
      lat = rl;
      lng = rln;
    } else if (dl != null && dln != null) {
      lat = dl;
      lng = dln;
    }
    const pts = [];
    if (rl != null && rln != null) pts.push([rl, rln]);
    if (dl != null && dln != null) pts.push([dl, dln]);
    const z = pts.length >= 2 ? 14 : 13;
    return { center: [lat, lng], zoom: z, fitPoints: pts };
  }, [rl, rln, dl, dln]);

  const riderNextActions = () => {
    const st = delivery?.currentStage;
    if (!st) return [];
    if (st === "ready_for_pickup") return [{ stage: "picked_up", label: "Mark picked up" }];
    if (st === "picked_up") return [{ stage: "on_the_way", label: "On the way" }];
    if (st === "on_the_way") return [{ stage: "delivered", label: "Mark delivered" }];
    return [];
  };

  const wrapCls = className || "";
  const isModal = variant === "trackModal";
  const recentLive = mode === "buyer" && Date.now() - lastLivePulse < 12000;

  if (loading) {
    return el(
      "div",
      {
        className: `flex min-h-[120px] items-center justify-center rounded-2xl border border-sky-300/35 bg-gradient-to-br from-sky-50/90 to-white dark:from-night-950/80 dark:to-night-900 ${wrapCls}`
      },
      el(
        "div",
        { className: "flex items-center gap-2 text-sm text-slate-600 dark:text-slate-300" },
        el(
          "span",
          { className: "h-5 w-5 animate-spin rounded-full border-2 border-sky-400 border-t-transparent" },
          null
        ),
        "Fetching live tracking…"
      )
    );
  }

  if (fetchErr) {
    return el("p", { className: `text-sm text-amber-700 dark:text-amber-200/90 ${wrapCls}` }, fetchErr);
  }

  if (!delivery) {
    return el(
      "div",
      {
        className: `rounded-2xl border border-dashed border-slate-300/80 bg-slate-50/90 px-4 py-8 text-center text-sm text-slate-600 dark:border-white/15 dark:bg-white/5 dark:text-slate-400 ${wrapCls}`
      },
      "Delivery tracking unlocks once the order is paid and the seller attaches campus delivery."
    );
  }

  const history = Array.isArray(delivery.statusHistory) ? [...delivery.statusHistory].reverse() : [];
  const eta = delivery.estimatedArrivalMinutes;
  const showRiderControls =
    mode === "rider" && delivery.currentStage !== "delivered" && delivery.currentStage !== "cancelled";

  const linePositions =
    rl != null && rln != null && dl != null && dln != null
      ? [
          [rl, rln],
          [dl, dln]
        ]
      : null;

  /* Progress index for decorative step bar */
  const curIdx =
    typeof delivery?.currentStage === "string"
      ? STAGE_ORDER.includes(delivery.currentStage)
        ? STAGE_ORDER.indexOf(delivery.currentStage)
        : 0
      : 0;

  const mapHeightClass = isModal ? "min-h-[220px] h-[260px] sm:h-[280px]" : "h-52 sm:h-60";

  return el("div", { className: `space-y-4 ${wrapCls}` }, [
    el(
      "div",
      {
        key: "hero",
        className: `relative overflow-hidden rounded-3xl border p-4 ${
          isModal
            ? "border-violet-200/75 bg-gradient-to-br from-white via-white to-violet-50/50 shadow-lg shadow-violet-500/10 dark:border-violet-500/20 dark:from-night-900 dark:via-night-900 dark:to-violet-950/30"
            : "border-white/15 bg-white/40 dark:bg-night-900/40"
        }`
      },
      [
        el(
          "div",
          {
            key: "row-top",
            className: "mb-4 flex flex-wrap items-start justify-between gap-3"
          },
          [
            el("div", { key: "l", className: "min-w-0 flex-1 space-y-2" }, [
              el(
                "p",
                { className: "text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400" },
                "Current status"
              ),
              el(
                "div",
                { className: "flex flex-wrap items-center gap-2" },
                [
                  el(
                    "span",
                    {
                      className:
                        "inline-flex items-center rounded-full bg-sky-500/15 px-3 py-1 text-sm font-bold text-sky-800 shadow-sm dark:bg-sky-500/20 dark:text-sky-100"
                    },
                    STAGE_LABELS[delivery.currentStage] || delivery.currentStage
                  ),
                  eta != null && Number.isFinite(eta)
                    ? el(
                        "span",
                        {
                          className:
                            "inline-flex items-center rounded-full border border-emerald-300/70 bg-emerald-50 px-3 py-1 text-xs font-semibold text-emerald-800 dark:border-emerald-500/30 dark:bg-emerald-950/40 dark:text-emerald-100"
                        },
                        `ETA ~${eta} min`
                      )
                    : null,
                  rider?.displayName
                    ? el(
                        "span",
                        {
                          className:
                            "inline-flex items-center gap-1 rounded-full border border-slate-200/95 bg-white/90 px-2.5 py-1 text-xs font-medium text-slate-700 dark:border-white/10 dark:bg-white/5 dark:text-slate-200"
                        },
                        [el(Bike, { key: "i", className: "h-3.5 w-3.5 text-violet-500" }), ` ${rider.displayName}`]
                      )
                    : null
                ].filter(Boolean)
              )
            ]),
            mode === "buyer"
              ? el(
                  "div",
                  {
                    key: "live-pill",
                    className:
                      "flex shrink-0 flex-col items-end gap-1 text-right text-[11px] font-semibold uppercase tracking-wide"
                  },
                  [
                    el(
                      "span",
                      {
                        className: `inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 font-bold ${
                          liveConnected && recentLive
                            ? "bg-emerald-500/90 text-white shadow-emerald-500/30 shadow-md"
                            : liveConnected
                              ? "border border-emerald-400/50 bg-emerald-500/10 text-emerald-800 dark:text-emerald-200"
                              : "border border-slate-200 bg-slate-100 text-slate-600 dark:border-white/10 dark:bg-white/10 dark:text-slate-300"
                        }`
                      },
                      [
                        el(Radio, {
                          key: "ic",
                          className: `h-3.5 w-3.5 ${recentLive ? "animate-pulse" : ""}`
                        }),
                        liveConnected ? (recentLive ? "Live updates" : "Connected") : "Reconnecting…"
                      ]
                    ),
                    rl != null && rln != null
                      ? el("span", { className: "font-mono normal-case text-[10px] font-medium text-violet-600 dark:text-violet-300" }, [
                          dl != null && dln != null ? "Map + courier position" : "Courier on map"
                        ])
                      : el("span", { className: "normal-case font-medium text-slate-500 dark:text-slate-400" }, [
                          dl != null && dln != null ? "Awaiting courier GPS…" : "Drop-off geo pending…"
                        ])
                  ].filter(Boolean)
                )
              : null
          ].filter(Boolean)
        ),

        /* Step progress */
        el(
          "div",
          {
            key: "steps",
            className: "mb-4 hidden items-center justify-between gap-1 sm:flex"
          },
          ["Placed", "Confirmed", "Prep", "Ready", "Pickup", "En route", "Done"].map((label, i) =>
            el(
              "div",
              {
                key: label,
                className: "flex min-w-0 flex-1 flex-col items-center text-center"
              },
              [
                el("div", {
                  className: `mb-1 h-2.5 w-2.5 shrink-0 rounded-full ${
                    i < curIdx
                      ? "bg-sky-500 shadow-sm"
                      : i === curIdx
                        ? "bg-violet-500 shadow-[0_0_0_5px_rgba(167,139,250,0.28)] dark:shadow-[0_0_0_5px_rgba(139,92,246,0.28)]"
                        : "bg-slate-300 dark:bg-slate-600"
                  }`
                }),
                el(
                  "span",
                  {
                    className: `block max-w-[4.5rem] truncate text-[8px] font-bold uppercase leading-tight sm:max-w-none sm:text-[9px] ${
                      i <= curIdx ? "text-sky-700 dark:text-sky-200" : "text-slate-400 dark:text-slate-500"
                    }`
                  },
                  label
                )
              ]
            )
          )
        ),

        el(
          "div",
          {
            key: "map-wrap",
            className: `${mapHeightClass} relative z-0 w-full overflow-hidden rounded-2xl border border-white/40 shadow-inner ring-1 ring-sky-400/15 dark:border-white/10 dark:ring-white/10`
          },
          el(
            MapContainer,
            {
              center,
              zoom,
              scrollWheelZoom: false,
              className: `h-full w-full [&_.leaflet-control-zoom]:rounded-xl [&_.leaflet-control-zoom]:shadow-md`
            },
            fitPoints.length >= 2 ? el(FitDeliveryBounds, { points: fitPoints }) : el(MapRecenter, { center, zoom }),
            el(TileLayer, { attribution: OSM_TILE.attribution, url: OSM_TILE.url }),
            dl != null && dln != null
              ? el(Marker, { position: [dl, dln], icon: DROPOFF_MARKER_ICON }, el(Popup, null, "Drop-off"))
              : null,
            rl != null && rln != null
              ? el(
                  Marker,
                  {
                    key: recentLive ? `rider-${lastLivePulse}` : "rider",
                    position: [rl, rln],
                    icon: RIDER_MARKER_ICON
                  },
                  el(Popup, null, "Courier · live location")
                )
              : null,
            linePositions
              ? el(Polyline, {
                  positions: linePositions,
                  pathOptions: { color: "#6366f1", weight: 4, opacity: 0.82, dashArray: "10 12" }
                })
              : null
          )
        )
      ].filter(Boolean)
    ),

    history.length > 0
      ? el(
          "div",
          {
            key: "hist",
            className:
              "rounded-3xl border border-slate-200/90 bg-white/90 px-4 py-4 shadow-sm dark:border-white/10 dark:bg-night-950/60"
          },
          [
            el(
              "p",
              {
                key: "h-t",
                className:
                  "mb-3 flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-slate-500 dark:text-slate-400"
              },
              [
                el(Clock, { key: "ic", className: "h-3.5 w-3.5 text-violet-500" }),
                "Delivery timeline"
              ]
            ),
            el(
              "ul",
              { className: "relative mx-1 space-y-0 pl-0" },
              history.slice(0, 14).map((row, idx) => {
                const Ic = timelineIcon(row.stage);
                const t = row.at ? formatFriendlyTime(row.at) : "";
                const showLine = idx < Math.min(history.length, 14) - 1;
                return el(
                  "li",
                  {
                    key: `${String(row.stage)}-${idx}-${row.at}`,
                    className: "relative flex gap-4 pb-5 last:pb-0"
                  },
                  [
                    el("div", { key: "rail", className: "relative flex w-11 shrink-0 flex-col items-center" }, [
                      el(
                        "div",
                        {
                          className:
                            "relative z-[1] grid h-10 w-10 place-items-center rounded-2xl border border-white/70 bg-gradient-to-br from-white to-violet-50 shadow-md ring-2 ring-violet-200/60 dark:border-white/10 dark:from-night-900 dark:to-violet-950/80 dark:ring-violet-500/30"
                        },
                        el(Ic, { className: "h-5 w-5 text-violet-600 dark:text-violet-300" })
                      ),
                      showLine
                        ? el("div", {
                            className:
                              "absolute left-1/2 top-11 h-[calc(100%-18px)] w-0.5 -translate-x-1/2 bg-gradient-to-b from-violet-300 to-sky-200/70 dark:from-violet-500/60 dark:to-sky-600/35"
                          })
                        : null
                    ]),
                    el(
                      "div",
                      {
                        key: "txt",
                        className:
                          "-mt-1 min-w-0 flex-1 rounded-2xl border border-slate-100/95 bg-slate-50/80 px-3 py-2.5 dark:border-white/5 dark:bg-white/5"
                      },
                      [
                        el(
                          "p",
                          { className: "text-sm font-bold text-slate-900 dark:text-white" },
                          STAGE_LABELS[row.stage] || row.stage
                        ),
                        row.note
                          ? el("p", { className: "mt-1 text-xs leading-snug text-slate-600 dark:text-slate-400" }, row.note)
                          : null,
                        t ? el("p", { className: "mt-1.5 text-[11px] font-medium text-slate-400 dark:text-slate-500" }, t) : null
                      ].filter(Boolean)
                    )
                  ]
                );
              })
            )
          ]
        )
      : null,

    showRiderControls
      ? el("div", { key: "rider-act", className: "flex flex-col gap-2 rounded-3xl border border-white/15 bg-white/40 p-3 dark:bg-night-900/40" }, [
          el(
            "p",
            { className: "text-[11px] font-bold uppercase tracking-wide text-slate-600 dark:text-slate-400" },
            "Rider actions"
          ),
          el("div", { className: "flex flex-wrap gap-2" }, [
            ...riderNextActions().map((a) =>
              el(
                "button",
                {
                  key: a.stage,
                  type: "button",
                  disabled: Boolean(busyStage),
                  className:
                    "inline-flex items-center rounded-xl bg-gradient-to-br from-sky-500 to-blue-600 px-3 py-2 text-xs font-bold text-white shadow-md shadow-sky-900/20 hover:brightness-110 disabled:opacity-60",
                  onClick: () => patchStage(a.stage)
                },
                busyStage === a.stage ? "Saving…" : a.label
              )
            ),
            el(
              "button",
              {
                type: "button",
                className: `rounded-xl border px-3 py-2 text-xs font-bold ${
                  geoSharing
                    ? "border-emerald-500 bg-emerald-600 text-white"
                    : "border-slate-200 bg-white/80 text-slate-900 dark:border-white/15 dark:bg-night-950/80 dark:text-slate-50"
                }`,
                onClick: () => {
                  setGeoErr("");
                  setGeoSharing((x) => !x);
                }
              },
              geoSharing ? "Stop sharing location" : "Share my GPS"
            )
          ]),
          geoErr ? el("p", { className: "text-xs text-rose-600 dark:text-rose-300" }, geoErr) : null
        ])
      : null
  ].filter(Boolean));
}
